/**
 * Deciding whether a cohort's pull request really merged.
 *
 * A build unit's `build_result` is released through a handoff whose external
 * wait is `github_review`. Something outside the run has to say that wait is
 * over, and "something said so" is not good enough: the whole point of the wait
 * is that the cohort's work landed, so the evidence has to be checked against
 * what the build itself reported opening.
 *
 * The check is deliberately graded rather than all-or-nothing. Identity — the
 * pull request URL and the head branch — comes from the cohort's own
 * `pr_summary` artifact and is always available, so it is always checked; those
 * two are what stop a merge of some other branch being accepted here. The forge
 * binding and the expected base branch come from an Epic profile, which not
 * every run has. v1 refused outright without one. Refusing means a run launched
 * without an Epic can never finish, so an absent expectation is skipped and
 * recorded as skipped instead.
 */
import type { ForgeRepositoryIdentity } from "../domain/epic";
import type { ArtifactId, JsonValue, StageInstanceId, UnitId, WorkflowRunId } from "../domain/primitives";
import {
  parseGithubPullRequestIdentity, pullRequestMismatch, pullRequestUrlsMatch, repositoriesMatch,
  type PullRequestMismatch, type PullRequestObservation,
} from "./pull-request";

/** The run-owned facts required to reconcile one cohort's external handoff. */
export interface RunOwnedCohortHandoff {
  readonly run_id: WorkflowRunId;
  readonly stage_instance_id: StageInstanceId;
  readonly unit_id: UnitId;
  readonly repository_key: string;
  readonly handoff_artifact_id: ArtifactId;
  readonly handoff_slot_state: "empty" | "pending" | "released" | "invalidated";
  readonly handoff_body: JsonValue;
  readonly summary_body: JsonValue;
}

/** What the run expects this cohort's pull request to be. */
export interface ExpectedCohortPullRequest {
  readonly run_id: WorkflowRunId;
  readonly stage_instance_id: StageInstanceId;
  readonly unit_id: UnitId;
  readonly repository_key: string;
  /** Where the build reported opening the pull request. */
  readonly url: string;
  /** The branch the build reported pushing. */
  readonly head_branch: string;
  /** The branch a cohort PR must target, when the run declares one. */
  readonly base_branch: string | null;
  /** The forge repository the run is bound to, when it is bound to one. */
  readonly forge_repository: ForgeRepositoryIdentity | null;
}

export interface CohortPullRequestReconciliation {
  readonly run_id: WorkflowRunId;
  readonly stage_instance_id: StageInstanceId;
  readonly unit_id: UnitId;
  readonly repository_key: string;
  /** Null only for rows written before handoff identity was persisted. */
  readonly handoff_artifact_id: ArtifactId | null;
  readonly observation: PullRequestObservation;
  readonly mismatch: PullRequestMismatch | null;
  readonly completed_at: string | null;
  readonly updated_at: string;
}

/**
 * What the run should do with an observation.
 *
 * `merged` is the only outcome that completes the external wait. `waiting` is a
 * pull request that is genuinely still open — not an error, just not yet.
 */
export type CohortPullRequestOutcome =
  | { readonly kind: "merged" }
  | { readonly kind: "waiting" }
  | { readonly kind: "already_completed" }
  | { readonly kind: "mismatch"; readonly mismatch: PullRequestMismatch }
  | { readonly kind: "ignored_stale"; readonly mismatch: PullRequestMismatch };

export interface ReconcileCohortPullRequestInput {
  readonly expected: ExpectedCohortPullRequest;
  readonly handoff_artifact_id: ArtifactId;
  readonly observation: PullRequestObservation;
  readonly previous: CohortPullRequestReconciliation | null;
  readonly reconciled_at: string;
}

export interface ReconciledCohortPullRequest {
  readonly outcome: CohortPullRequestOutcome;
  readonly reconciliation: CohortPullRequestReconciliation;
}

/** A prior completion is historical only when a different handoff is pending. */
export const reconciliationForHandoff = (
  previous: CohortPullRequestReconciliation | null,
  handoffArtifactId: ArtifactId,
  slotState: RunOwnedCohortHandoff["handoff_slot_state"],
): CohortPullRequestReconciliation | null =>
  previous?.completed_at && slotState === "pending" && previous.handoff_artifact_id !== handoffArtifactId
    ? { ...previous, completed_at: null }
    : previous;

/** The first expectation the observation fails, or null if it meets them all. */
const findMismatch = (expected: ExpectedCohortPullRequest, observation: PullRequestObservation): PullRequestMismatch | null => {
  const identity = parseGithubPullRequestIdentity(expected.url);
  if (!identity) {
    return pullRequestMismatch("pull_request_mismatch", "the cohort's pr_summary URL is not a canonical GitHub pull request URL");
  }
  if (!pullRequestUrlsMatch(expected.url, observation.url)) {
    return pullRequestMismatch("pull_request_mismatch", "observed pull request is not the one the build reported opening");
  }
  // The observation names its repository twice — in its URL and in its own
  // fields. They have to agree, or a caller could point a merged PR's URL at
  // one repository while reporting the state of another.
  if (!repositoriesMatch(observation.owner, observation.name, identity.owner, identity.name)) {
    return pullRequestMismatch("repository_mismatch", "observed pull request belongs to another repository than its own URL");
  }
  if (expected.forge_repository && !repositoriesMatch(observation.owner, observation.name, expected.forge_repository.owner, expected.forge_repository.name)) {
    return pullRequestMismatch("repository_mismatch", "observed pull request does not belong to the repository this run is bound to");
  }
  if (observation.head_branch !== expected.head_branch) {
    return pullRequestMismatch("head_branch_mismatch", `observed head branch '${observation.head_branch}' is not the cohort branch '${expected.head_branch}'`);
  }
  if (expected.base_branch !== null && observation.base_branch !== expected.base_branch) {
    return pullRequestMismatch("base_branch_mismatch", `observed base branch '${observation.base_branch}' is not the branch the cohort targets, '${expected.base_branch}'`);
  }
  if (observation.state === "closed_unmerged") {
    return pullRequestMismatch("closed_without_merge", "pull request was closed without merging");
  }
  if (observation.state === "merged" && observation.merged_at === null) {
    return pullRequestMismatch("pull_request_mismatch", "merged observation carries no merged_at evidence");
  }
  return null;
};

/**
 * `completed_at` is deliberately not set here even for a merge. It means "this
 * is the observation that closed the wait", and only the caller holding the
 * handoff knows whether the wait was open to be closed — a pull request can be
 * merged before the assessor has approved it, and recording that as completion
 * would leave a wait that later opens and never closes.
 */
export const reconcileCohortPullRequest = (input: ReconcileCohortPullRequestInput): ReconciledCohortPullRequest => {
  const record = (mismatch: PullRequestMismatch | null): CohortPullRequestReconciliation => ({
    run_id: input.expected.run_id, stage_instance_id: input.expected.stage_instance_id, unit_id: input.expected.unit_id,
    repository_key: input.expected.repository_key, handoff_artifact_id: input.handoff_artifact_id,
    observation: input.observation, mismatch,
    completed_at: input.previous?.completed_at ?? null, updated_at: input.reconciled_at,
  });

  if (input.previous?.completed_at) return { outcome: { kind: "already_completed" }, reconciliation: input.previous };
  // An observation older than the one already recorded says nothing new, and
  // acting on it would let a stale "open" undo a merge already reconciled.
  if (input.previous && Date.parse(input.previous.observation.observed_at) > Date.parse(input.observation.observed_at)) {
    return {
      outcome: { kind: "ignored_stale", mismatch: pullRequestMismatch("stale_observation", "observation is older than the reconciliation already recorded") },
      reconciliation: input.previous,
    };
  }

  const mismatch = findMismatch(input.expected, input.observation);
  if (mismatch) return { outcome: { kind: "mismatch", mismatch }, reconciliation: record(mismatch) };
  if (input.observation.state === "open") return { outcome: { kind: "waiting" }, reconciliation: record(null) };
  return { outcome: { kind: "merged" }, reconciliation: record(null) };
};

/** Stamps a reconciliation as the one that closed the cohort's external wait. */
export const withCompletion = (reconciliation: CohortPullRequestReconciliation, completed_at: string): CohortPullRequestReconciliation =>
  ({ ...reconciliation, completed_at: reconciliation.completed_at ?? completed_at, updated_at: completed_at });

/**
 * The evidence an operator supplies when they confirm a merge themselves.
 *
 * The poller is the normal path; this is the fallback for when it cannot see
 * the repository — no token, a forge the reader does not speak, a merge done
 * somewhere the API does not reflect. It asserts nothing the operator did not:
 * the identity is copied from what the build reported, so the same expectations
 * are checked against it as against a polled observation, and the record says
 * plainly that a human is the source.
 */
export const operatorMergedObservation = (expected: ExpectedCohortPullRequest, confirmedAt: string): PullRequestObservation | null => {
  const identity = parseGithubPullRequestIdentity(expected.url);
  if (!identity) return null;
  return {
    provider: "github", owner: identity.owner, name: identity.name, number: identity.number, url: expected.url,
    head_branch: expected.head_branch, base_branch: expected.base_branch ?? "", head_sha: null,
    state: "merged", source: "manual_recheck", observed_at: confirmedAt, merged_at: confirmedAt,
  };
};

import type {
  EpicRepositoryBinding,
  EpicWorkflowProfile,
  EpicWorkflowProfileId,
  PullRequestReference,
} from "../domain/epic";
import { err, ok, type Result } from "../domain/primitives";
import { parseGithubPullRequestIdentity, pullRequestMismatch, repositoriesMatch, type PullRequestMismatch, type PullRequestObservation } from "./pull-request";

// The pull-request vocabulary is shared with cohort reconciliation; its
// types are re-exported here so existing callers keep one import path. The
// parser itself is not re-exported — import it from ./pull-request directly.
export type { ObservedPullRequestState, PullRequestMismatch, PullRequestMismatchKind, PullRequestObservation, PullRequestObservationSource } from "./pull-request";

export interface FinalPullRequestReconciliation {
  readonly epic_profile_id: EpicWorkflowProfileId;
  readonly repository_key: string;
  readonly observation: PullRequestObservation;
  readonly mismatch: PullRequestMismatch | null;
  readonly merged_evidence_at: string | null;
  readonly confirmation_idempotency_key: string | null;
  readonly operator_comment: string | null;
  readonly confirmed_at: string | null;
  readonly updated_at: string;
}

export interface ConfirmFinalPullRequestRequest {
  readonly idempotency_key: string;
  readonly operator_comment?: string;
}

export type ObserveFinalPullRequestOutcome =
  | "waiting"
  | "completed"
  | "mismatch"
  | "ignored_stale"
  | "awaiting_external_confirmation";

export interface FinalPullRequestProjection {
  readonly outcome: ObserveFinalPullRequestOutcome | "already_completed";
  readonly profile: EpicWorkflowProfile;
  readonly reconciliation: FinalPullRequestReconciliation | null;
}

export interface FinalPullRequestDomainError {
  readonly operation: "observe_final_pull_request" | "confirm_final_pull_request";
  readonly kind:
    | "not_eligible"
    | "profile_not_found"
    | "repository_not_bound"
    | "missing_repository_identity"
    | "invalid_pull_request_url"
    | "invalid_idempotency_key"
    | "invalid_policy"
    | "missing_merged_evidence"
    | "idempotency_conflict";
  readonly detail: string;
}

export interface ObserveFinalPullRequestInput {
  readonly profile: EpicWorkflowProfile;
  readonly repository_key: string;
  readonly observation: PullRequestObservation;
  readonly previous: FinalPullRequestReconciliation | null;
  readonly is_final_integration_eligible: boolean;
  readonly updated_at: string;
}

export interface ConfirmFinalPullRequestInput {
  readonly profile: EpicWorkflowProfile;
  readonly repository_key: string;
  readonly reconciliation: FinalPullRequestReconciliation | null;
  readonly request: ConfirmFinalPullRequestRequest;
  readonly is_final_integration_eligible: boolean;
  readonly confirmed_at: string;
}

const replaceRepository = (
  profile: EpicWorkflowProfile,
  repositoryKey: string,
  transform: (repository: EpicRepositoryBinding) => EpicRepositoryBinding,
  updatedAt: string,
): EpicWorkflowProfile => {
  const repositories = profile.repositories.map((repository) =>
    repository.repository_key === repositoryKey ? transform(repository) : repository);
  const lifecycle_state = repositories.every((repository) => repository.final_merge_state === "merged")
    ? "completed"
    : "final_integration";
  return { ...profile, repositories, lifecycle_state, updated_at: updatedAt };
};

const pullRequestReferencesMatch = (left: PullRequestReference, observation: PullRequestObservation): boolean => {
  const leftIdentity = parseGithubPullRequestIdentity(left.url);
  const rightIdentity = parseGithubPullRequestIdentity(observation.url);
  return left.number === observation.number
    && leftIdentity !== null
    && rightIdentity !== null
    && leftIdentity.number === rightIdentity.number
    && repositoriesMatch(leftIdentity.owner, leftIdentity.name, rightIdentity.owner, rightIdentity.name);
};

export const observeFinalPullRequest = (
  input: ObserveFinalPullRequestInput,
): Result<FinalPullRequestProjection, FinalPullRequestDomainError> => {
  const operation = "observe_final_pull_request" as const;
  if (!input.is_final_integration_eligible) return err({ operation, kind: "not_eligible", detail: "final integration requires every build cohort and assessment to be complete" });
  const repository = input.profile.repositories.find((candidate) => candidate.repository_key === input.repository_key);
  if (!repository) return err({ operation, kind: "repository_not_bound", detail: "repository is not bound to the Epic" });
  if (repository.final_merge_state === "merged") return ok({ outcome: "already_completed", profile: input.profile, reconciliation: input.previous });
  if (!repository.forge_repository) return err({ operation, kind: "missing_repository_identity", detail: "Epic repository has no durable forge identity" });
  const urlIdentity = parseGithubPullRequestIdentity(input.observation.url);
  if (!urlIdentity) return err({ operation, kind: "invalid_pull_request_url", detail: "observation URL is not a canonical GitHub PR URL" });
  if (input.previous && Date.parse(input.previous.observation.observed_at) > Date.parse(input.observation.observed_at)) {
    return ok({ outcome: "ignored_stale", profile: input.profile, reconciliation: input.previous });
  }

  // The final pull request carries the epic's work home: its head is the run's
  // base branch, and its base is where that branch was cut from.
  const reference = repository.final_pull_request ?? {
    number: urlIdentity.number,
    url: input.observation.url,
    head_branch: input.profile.base_branch,
    base_branch: repository.integration_branch,
  };
  let finding: PullRequestMismatch | null = null;
  if (!repositoriesMatch(urlIdentity.owner, urlIdentity.name, repository.forge_repository.owner, repository.forge_repository.name)) {
    finding = pullRequestMismatch("repository_mismatch", "final pull request URL does not belong to the Epic repository binding");
  } else if (!repositoriesMatch(input.observation.owner, input.observation.name, repository.forge_repository.owner, repository.forge_repository.name)) {
    finding = pullRequestMismatch("repository_mismatch", "observed pull request belongs to another repository");
  } else if (!pullRequestReferencesMatch(reference, input.observation)) {
    finding = pullRequestMismatch("pull_request_mismatch", "observed pull request does not match the build's durable PR identity");
  } else if (input.observation.head_branch !== input.profile.base_branch) {
    finding = pullRequestMismatch("head_branch_mismatch", "observed pull request head branch does not match the epic's base branch");
  } else if (input.observation.base_branch !== repository.integration_branch) {
    finding = pullRequestMismatch("base_branch_mismatch", "observed pull request base branch does not match the repository integration branch");
  } else if (input.observation.state === "closed_unmerged") {
    finding = pullRequestMismatch("closed_without_merge", "pull request closed without merging into the integration branch");
  } else if (input.observation.state === "merged" && input.observation.merged_at === null) {
    finding = pullRequestMismatch("pull_request_mismatch", "merged observation is missing merged_at evidence");
  }

  const hasMergedEvidence = finding === null && input.observation.state === "merged";
  const reconciliation: FinalPullRequestReconciliation = {
    epic_profile_id: input.profile.id,
    repository_key: input.repository_key,
    observation: input.observation,
    mismatch: finding,
    merged_evidence_at: hasMergedEvidence ? input.observation.merged_at : input.previous?.merged_evidence_at ?? null,
    confirmation_idempotency_key: input.previous?.confirmation_idempotency_key ?? null,
    operator_comment: input.previous?.operator_comment ?? null,
    confirmed_at: input.previous?.confirmed_at ?? null,
    updated_at: input.updated_at,
  };
  const shouldRegisterReference = finding === null || finding.kind === "closed_without_merge";
  const nextState = finding?.kind === "closed_without_merge"
    ? "closed_without_merge"
    : finding !== null
      ? repository.final_merge_state
      : input.observation.state === "open"
        ? "pull_request_open"
        : input.profile.final_merge_policy === "guarded" ? "merged" : "awaiting_confirmation";
  const profile = replaceRepository(input.profile, input.repository_key, (current) => ({
    ...current,
    final_pull_request: shouldRegisterReference ? reference : current.final_pull_request,
    final_merge_state: nextState,
  }), input.updated_at);
  const outcome: ObserveFinalPullRequestOutcome = finding !== null
    ? "mismatch"
    : input.observation.state === "open"
      ? "waiting"
      : input.profile.final_merge_policy === "guarded" ? "completed" : "awaiting_external_confirmation";
  return ok({ outcome, profile, reconciliation });
};

export const confirmFinalPullRequest = (
  input: ConfirmFinalPullRequestInput,
): Result<FinalPullRequestProjection, FinalPullRequestDomainError> => {
  const operation = "confirm_final_pull_request" as const;
  if (input.request.idempotency_key.trim() === "") return err({ operation, kind: "invalid_idempotency_key", detail: "idempotency_key must not be empty" });
  if (!input.is_final_integration_eligible) return err({ operation, kind: "not_eligible", detail: "final integration requires every build cohort and assessment to be complete" });
  if (input.profile.final_merge_policy !== "external_confirmation") return err({ operation, kind: "invalid_policy", detail: "explicit confirmation is only valid for external_confirmation policy" });
  if (!input.reconciliation?.merged_evidence_at) return err({ operation, kind: "missing_merged_evidence", detail: "final pull request has no durable merged evidence" });
  if (input.reconciliation.confirmation_idempotency_key !== null
      && input.reconciliation.confirmation_idempotency_key !== input.request.idempotency_key) {
    return err({ operation, kind: "idempotency_conflict", detail: "final pull request was confirmed with a different idempotency key" });
  }
  if (!input.profile.repositories.some((repository) => repository.repository_key === input.repository_key)) {
    return err({ operation, kind: "repository_not_bound", detail: "repository is not bound to the Epic" });
  }
  const reconciliation: FinalPullRequestReconciliation = {
    ...input.reconciliation,
    confirmation_idempotency_key: input.request.idempotency_key,
    operator_comment: input.request.operator_comment ?? null,
    confirmed_at: input.reconciliation.confirmed_at ?? input.confirmed_at,
    updated_at: input.confirmed_at,
  };
  const profile = replaceRepository(input.profile, input.repository_key, (repository) => ({
    ...repository,
    final_merge_state: "merged",
  }), input.confirmed_at);
  return ok({ outcome: "completed", profile, reconciliation });
};

/**
 * What the run knows about a pull request on a forge, and how it decides that
 * what it observed is the pull request it was waiting for.
 *
 * Two different waits reconcile against this vocabulary — a cohort's
 * `github_review` handoff and an epic's final integration merge — so the
 * observation, the mismatch taxonomy and the URL identity live here rather than
 * inside either one.
 */
export type PullRequestObservationSource = "poll" | "webhook" | "manual_recheck";
export type ObservedPullRequestState = "open" | "merged" | "closed_unmerged";

export interface PullRequestObservation {
  readonly provider: "github";
  readonly owner: string;
  readonly name: string;
  readonly number: number;
  readonly url: string;
  readonly head_branch: string;
  readonly base_branch: string;
  readonly head_sha: string | null;
  readonly state: ObservedPullRequestState;
  readonly source: PullRequestObservationSource;
  readonly observed_at: string;
  readonly merged_at: string | null;
}

export type PullRequestMismatchKind =
  | "missing_repository_identity"
  | "repository_mismatch"
  | "pull_request_mismatch"
  | "head_branch_mismatch"
  | "base_branch_mismatch"
  | "closed_without_merge"
  | "stale_observation";

export interface PullRequestMismatch {
  readonly kind: PullRequestMismatchKind;
  readonly detail: string;
}

export const pullRequestMismatch = (kind: PullRequestMismatchKind, detail: string): PullRequestMismatch => ({ kind, detail });

export interface PullRequestIdentity {
  readonly owner: string;
  readonly name: string;
  readonly number: number;
}

export const parseGithubPullRequestIdentity = (url: string): PullRequestIdentity | null => {
  const match = /^https:\/\/github\.com\/([^/]+)\/([^/]+)\/pull\/([1-9][0-9]*)\/?$/.exec(url);
  if (!match) return null;
  return { owner: match[1]!, name: match[2]!, number: Number(match[3]) };
};

/** Forge repository names are case-insensitive; the rest of a URL is not. */
export const repositoriesMatch = (leftOwner: string, leftName: string, rightOwner: string, rightName: string): boolean =>
  leftOwner.toLocaleLowerCase("en-US") === rightOwner.toLocaleLowerCase("en-US")
  && leftName.toLocaleLowerCase("en-US") === rightName.toLocaleLowerCase("en-US");

/** Whether two URLs name the same pull request, ignoring owner/name casing. */
export const pullRequestUrlsMatch = (left: string, right: string): boolean => {
  const leftIdentity = parseGithubPullRequestIdentity(left);
  const rightIdentity = parseGithubPullRequestIdentity(right);
  return leftIdentity !== null && rightIdentity !== null
    && leftIdentity.number === rightIdentity.number
    && repositoriesMatch(leftIdentity.owner, leftIdentity.name, rightIdentity.owner, rightIdentity.name);
};

